import type { NewKnowledgeUnit, NewKnowledgeAsset, NewKnowledgeGraphEdge } from "@/lib/db/schema";
const U=(id:string,t:string,s:string,o:string,l:string,k:string[],g:string[],se:number):NewKnowledgeUnit=>({id,title:t,slug:s,learningObjective:o,cognitiveLevel:l,difficulty:se<10?"beginner":"intermediate",estimatedTimeMin:8,skills:k,tags:g,agentDomain:"nexus",version:1,status:"published"})as NewKnowledgeUnit;
const A=(aid:string,uid:string,ep:number,ab:string,na:string,en:string,pv:string|null,nx:string|null,lg:boolean):NewKnowledgeAsset=>({id:aid,knowledgeUnitId:uid,agentId:"nexus",season:ep<=10?6:ep<=20?7:ep<=30?8:ep<=40?9:10,episode:((ep-1)%10)+1,type:"episode",content:{abertura:ab,narrativa:na,pausas:[],encerramento:en},metadata:{xpReward:50,readingTimeMin:8,pauseCount:0,hasLogosGate:lg,prevEpisode:pv,nextEpisode:nx},source:"manual",status:"published",version:1})as NewKnowledgeAsset;
const E=(p:string):NewKnowledgeGraphEdge[]=>[{id:`kge-nexus-t0${Math.floor((parseInt(p.slice(3))-1)/10)+6}-${p.slice(0,3)}-${p.slice(4)}`,fromUnitId:`ku-nexus-t0${Math.floor((parseInt(p.slice(3))-1)/10)+6}-${p.slice(0,3)}`,toUnitId:`ku-nexus-t0${Math.floor((parseInt(p.slice(4))-1)/10)+6}-${p.slice(4)}`,relationship:"next",weight:1.0}];
const E0:NewKnowledgeGraphEdge[]=[];

/* ═══════════════════ TEMPORADA 6 — REDES NEURAIS BÁSICAS ═══════════════════ */
const s6=(n:number)=>`06-e${String(n).padStart(2,"0")}`;
// Helper local: create UNIT + ASSET + EDGES for one episode
function ep(n:number,t:string,obj:string,lvl:string,sk:string[],ab:string,na:string,enc:string,pv:string|null,nx:string|null,lg:boolean,prefix="06"){
  const uid=`ku-nexus-t${prefix}-e${String(n).padStart(2,"0")}`;
  return {UNIT:U(uid,t,`nexus-t${prefix}-e${String(n).padStart(2,"0")}-${t.toLowerCase().replace(/[^a-z0-9]+/g,"-").slice(0,40)}`,obj,lvl,sk,["ia","redes-neurais"],parseInt(prefix)),ASSET:A(`ka-nexus-t${prefix}-e${String(n).padStart(2,"0")}`,uid,n,ab,na,enc,pv,nx,lg),EDGES:lg?E0:n<10?E(`e${String(n).padStart(2,"0")}-e${String(n+1).padStart(2,"0")}`):E0};
}

// T06E01
const e01=ep(1,"O Neurônio Artificial","Reconhecer o neurônio artificial como unidade fundamental das redes neurais.","remember",["neuron","perceptron","activation"],"Você está dentro de um neurônio gigante. Dendritos brilham como cabos de fibra óptica. No centro, NEXUS flutua dentro do núcleo. 'Bem-vindo à unidade fundamental da inteligência artificial. Assim como seu cérebro tem 86 bilhões de neurônios, as redes neurais são feitas de neurônios artificiais. Vamos começar pelo mais simples.'","O perceptron, criado em 1958 por Frank Rosenblatt, é o neurônio artificial mais simples. Ele recebe várias entradas, multiplica cada uma por um peso, soma tudo e aplica uma função de ativação. Se o resultado passar de um limiar, o neurônio 'dispara'. É exatamente assim que seu cérebro funciona — só que com muito mais complexidade.","'Você conheceu a unidade básica. Mas um neurônio sozinho não faz nada. Amanhã, como conectar neurônios em camadas — a mágica das redes profundas.'",null,"Camadas e Conexões",false);
export const NEXUS_T06E01_UNIT=e01.UNIT;export const NEXUS_T06E01_ASSET=e01.ASSET;export const NEXUS_T06E01_EDGES=e01.EDGES;

const e02=ep(2,"Camadas e Conexões","Entender como neurônios se organizam em camadas para criar redes profundas.","understand",["layers","deep-learning","architecture"],"Milhares de neurônios se conectam ao seu redor — formando camadas que lembram um anfiteatro. Cada neurônio da camada 1 se conecta a todos da camada 2. NEXUS desenha as conexões no ar. 'Uma rede neural é como uma fábrica. A camada de entrada recebe a matéria-prima. As camadas ocultas processam. A camada de saída entrega o produto final.'","Redes profundas (deep learning) são simplesmente redes com MUITAS camadas ocultas. Cada camada aprende um nível diferente de abstração. A primeira camada pode aprender bordas. A segunda, formas. A terceira, objetos. A profundidade permite que a rede entenda conceitos cada vez mais complexos.","'Você viu as camadas. Mas como a rede APRENDE? Amanhã, o treinamento supervisionado — ensinar a rede com exemplos.'","O Neurônio Artificial","Treinamento Supervisionado",false);
export const NEXUS_T06E02_UNIT=e02.UNIT;export const NEXUS_T06E02_ASSET=e02.ASSET;export const NEXUS_T06E02_EDGES=e02.EDGES;

const e03=ep(3,"Treinamento Supervisionado","Aplicar treinamento supervisionado para ensinar redes neurais com dados rotulados.","understand",["supervised-learning","labels","loss-function"],"Uma sala de aula infinita. Milhões de cartões com imagens e respostas: 'gato', 'cachorro', 'carro'. NEXUS é o professor. 'Treinamento supervisionado é como ensinar uma criança: você mostra a foto e diz o nome. Depois de milhares de exemplos, a criança — ou a rede — aprende a reconhecer sozinha.'","O treinamento tem 3 ingredientes: (1) Dados rotulados — entrada + resposta correta. (2) Função de perda — mede o quanto a rede errou. (3) Otimizador — ajusta os pesos para errar menos na próxima. Repita milhares de vezes. A rede melhora a cada iteração.","'Você treinou sua primeira rede. Mas como ela decide SE deve ativar um neurônio? Amanhã, as funções de ativação.'","Camadas e Conexões","A Função de Ativação",true);
export const NEXUS_T06E03_UNIT=e03.UNIT;export const NEXUS_T06E03_ASSET=e03.ASSET;export const NEXUS_T06E03_EDGES=e03.EDGES;

const e04=ep(4,"A Função de Ativação","Aplicar funções de ativação para controlar o fluxo de informação nas redes.","apply",["activation-functions","relu","sigmoid"],"Você está num ginásio onde cada neurônio é um atleta. Alguns estão dormindo (valor 0). Outros estão explodindo de energia (valor alto). NEXUS ajusta um botão mestre. 'A função de ativação decide SE e QUANTO um neurônio transmite seu sinal para a próxima camada. Sem ela, a rede seria só uma multiplicação linear.'","As principais funções: Sigmoid — comprime entre 0 e 1, boa para probabilidades. ReLU — zera valores negativos, simples e eficiente. Softmax — transforma saídas em probabilidades, perfeita para classificação. A ReLU é a mais usada porque é rápida e resolve o problema do 'gradiente que desaparece'.","'Você dominou as ativações. Mas como o erro viaja PRA TRÁS na rede? Amanhã, backpropagation — o algoritmo que revolucionou o deep learning.'","Treinamento Supervisionado","Backpropagation",false);
export const NEXUS_T06E04_UNIT=e04.UNIT;export const NEXUS_T06E04_ASSET=e04.ASSET;export const NEXUS_T06E04_EDGES=e04.EDGES;

const e05=ep(5,"Backpropagation","Aplicar o algoritmo de retropropagação para ajustar pesos em redes profundas.","apply",["backpropagation","gradient","chain-rule"],"A rede está cometendo erros. Você vê o erro viajar como uma onda REVERSA — das saídas de volta para as entradas. NEXUS surfa nessa onda. 'Backpropagation é genial pela simplicidade: calcule o erro na saída. Propague esse erro de volta, camada por camada. Ajuste cada peso proporcionalmente à sua contribuição para o erro.'","O 'gradiente descendente' é como descer uma montanha no escuro. Você dá passos na direção que mais DESCE. O tamanho do passo é a 'taxa de aprendizado'. Passos grandes demais: você pode pular o vale. Passos pequenos demais: demora muito. Encontrar o equilíbrio é arte.","'Você surfou na onda do gradiente. Mas redes muito inteligentes decoram em vez de aprender. Amanhã, overfitting — o perigo da inteligência artificial.'","A Função de Ativação","Overfitting e Regularização",false);
export const NEXUS_T06E05_UNIT=e05.UNIT;export const NEXUS_T06E05_ASSET=e05.ASSET;export const NEXUS_T06E05_EDGES=e05.EDGES;

const e06=ep(6,"Overfitting e Regularização","Aplicar técnicas de regularização para evitar overfitting em redes neurais.","apply",["overfitting","regularization","dropout"],"A rede neural virou um aluno que DECOROU o gabarito da prova. Quando você mostra uma pergunta nova, ela falha completamente. NEXUS balança a cabeça. 'Overfitting: quando a rede memoriza os dados de treino em vez de aprender padrões reais. É como decorar respostas em vez de entender a matéria.'","Técnicas para combater: (1) Dropout — desligue neurônios aleatoriamente durante o treino. A rede aprende a ser redundante. (2) Regularização L2 — penalize pesos muito grandes. (3) Early stopping — pare o treino antes de começar a decorar. (4) Mais dados — sempre ajuda.","'Você aprendeu a regularizar. Agora vamos para arquiteturas especializadas. Amanhã, redes convolucionais — como as máquinas enxergam.'","Backpropagation","Redes Convolucionais",true);
export const NEXUS_T06E06_UNIT=e06.UNIT;export const NEXUS_T06E06_ASSET=e06.ASSET;export const NEXUS_T06E06_EDGES=e06.EDGES;

const e07=ep(7,"Redes Convolucionais","Aplicar CNNs para processamento e classificação de imagens.","apply",["cnn","convolution","image-recognition"],"Você está dentro de um olho mecânico. Camadas de filtros deslizam sobre uma imagem — cada uma detectando algo: bordas, texturas, formas. NEXUS aponta para os filtros. 'Redes Convolucionais (CNNs) são o motivo de reconhecimento facial, carros autônomos e diagnósticos médicos funcionarem. Cada filtro é um mini-especialista.'","Uma CNN tem 3 tipos de camada: (1) Convolução — aplica filtros que detectam padrões. (2) Pooling — reduz a resolução, mantendo o que importa. (3) Fully Connected — no final, classifica. O segredo: os filtros são APRENDIDOS, não programados. A rede descobre sozinha quais padrões importam.","'Você viu como as máquinas enxergam. Mas e quando os dados são sequenciais — texto, música, vídeo? Amanhã, redes recorrentes.'","Overfitting e Regularização","Redes Recorrentes",false);
export const NEXUS_T06E07_UNIT=e07.UNIT;export const NEXUS_T06E07_ASSET=e07.ASSET;export const NEXUS_T06E07_EDGES=e07.EDGES;

const e08=ep(8,"Redes Recorrentes","Aplicar RNNs e LSTMs para processamento de sequências temporais.","apply",["rnn","lstm","sequence-modeling"],"Os dados agora fluem como um rio — palavras, notas musicais, preços de ações. NEXUS cria um LOOP no fluxo: cada dado que passa alimenta o PRÓXIMO. 'Redes Recorrentes (RNNs) têm memória. Elas lembram do que veio antes. Perfeitas para tradução, legendagem e previsão de séries temporais.'","LSTM (Long Short-Term Memory) resolveu o maior problema das RNNs: memória curta. Ela tem 'portões' que decidem o que esquecer, o que lembrar e o que passar adiante. É como um assistente que anota o importante e descarta o resto.","'Você entendeu as RNNs. Mas a arquitetura que mudou o mundo veio em 2017. Amanhã, Transformers — a revolução da atenção.'","Redes Convolucionais","Transformers",false);
export const NEXUS_T06E08_UNIT=e08.UNIT;export const NEXUS_T06E08_ASSET=e08.ASSET;export const NEXUS_T06E08_EDGES=e08.EDGES;

const e09=ep(9,"Transformers","Analisar a arquitetura Transformer e seu papel revolucionário na IA moderna.","analyze",["transformers","attention","llm"],"Você está num salão onde cada palavra presta ATENÇÃO em todas as outras simultaneamente. NEXUS está no centro, orquestrando. 'Em 2017, o paper 'Attention Is All You Need' mudou tudo. Transformers não processam uma palavra por vez — elas veem a frase INTEIRA de uma vez e decidem quais partes são relevantes.'","O mecanismo de 'atenção' é a chave: para cada palavra, o modelo calcula o quanto ela deve prestar atenção em cada OUTRA palavra. Em 'o gato bebeu leite porque estava com SEDE', o modelo aprende que 'sede' se refere ao gato, não ao leite. Isso é atenção. ChatGPT, GPT-4, Claude — todos são Transformers.","'Você entendeu os Transformers. O futuro é construído sobre eles. Amanhã, vamos olhar para onde tudo isso está indo.'","Redes Recorrentes","O Futuro das Redes",true);
export const NEXUS_T06E09_UNIT=e09.UNIT;export const NEXUS_T06E09_ASSET=e09.ASSET;export const NEXUS_T06E09_EDGES=e09.EDGES;

const e10=ep(10,"O Futuro das Redes","Sintetizar o aprendizado sobre redes neurais e projetar tendências futuras.","evaluate",["future","trends","synthesis"],"Você está numa sala de controle que mostra o futuro: redes que aprendem sem supervisão, redes que geram arte, redes que descobrem medicamentos. NEXUS olha para o horizonte. 'Em 10 episódios, você foi do neurônio artificial até os Transformers. Mas a jornada está só começando.'","Grafos neurais, aprendizado auto-supervisionado, modelos multimodais — o futuro é rico. Mas o princípio permanece: neurônios, camadas, funções de ativação, backpropagation. Domine os fundamentos e você dominará qualquer arquitetura futura.","'Temporada 6 concluída. Você construiu as fundações das redes neurais. Na próxima temporada, vamos ensinar as máquinas a VER — bem-vindo à Visão Computacional.'","Transformers",null,false);
export const NEXUS_T06E10_UNIT=e10.UNIT;export const NEXUS_T06E10_ASSET=e10.ASSET;export const NEXUS_T06E10_EDGES=e10.EDGES;

/* ═══════════════════ TEMPORADA 7 — VISÃO COMPUTACIONAL ═══════════════════ */
// T07 episodes follow same compact pattern as T06
const tv=(n:number,t:string,obj:string,lvl:string,sk:string[],ab:string,na:string,enc:string,pv:string|null,nx:string|null,lg:boolean)=>{
  const uid=`ku-nexus-t07-e${String(n).padStart(2,"0")}`;
  return {UNIT:U(uid,t,`nexus-t07-e${String(n).padStart(2,"0")}-${t.toLowerCase().replace(/[^a-z0-9]+/g,"-").slice(0,40)}`,obj,lvl,sk,["ia","visao-computacional"],7),ASSET:A(`ka-nexus-t07-e${String(n).padStart(2,"0")}`,uid,n,ab,na,enc,pv,nx,lg),EDGES:lg?E0:n<10?E(`e${String(n).padStart(2,"0")}-e${String(n+1).padStart(2,"0")}`):E0};
};
const v01=tv(1,"O Olho da Máquina","Reconhecer os fundamentos da visão computacional.","remember",["computer-vision","image-processing"],"Uma câmera gigante flutua no centro da sala. Cada clique captura não apenas luz — mas SIGNIFICADO. NEXUS ajusta as lentes. 'Seus olhos capturam luz. Seu cérebro interpreta. A visão computacional faz o mesmo: sensores capturam pixels, algoritmos extraem significado.'","Em 2012, uma CNN chamada AlexNet reduziu o erro de classificação de imagens pela metade. Foi o momento 'iPhone' da visão computacional. De repente, máquinas podiam 'ver' melhor que humanos em tarefas específicas.","'Você abriu o olho da máquina. Amanhã, ensinar a máquina a ENCONTRAR objetos — detecção.'",null,"Detecção de Objetos",false);
export const NEXUS_T07E01_UNIT=v01.UNIT;export const NEXUS_T07E01_ASSET=v01.ASSET;export const NEXUS_T07E01_EDGES=v01.EDGES;
const v02=tv(2,"Detecção de Objetos","Entender como algoritmos detectam e localizam objetos em imagens.","understand",["object-detection","yolo","bounding-box"],"Sobre uma imagem de rua, caixas coloridas aparecem: azul para carros, verde para pessoas, vermelho para bicicletas. NEXUS desenha as caixas. 'Detecção de objetos responde DUAS perguntas: O QUE é isso? E ONDE está?'","O YOLO (You Only Look Once) revolucionou a detecção em 2015: em vez de analisar a imagem em partes, ele olha para a imagem INTEIRA uma única vez e prevê todas as caixas de uma vez. É tão rápido que funciona em vídeo em tempo real.","'Você detectou objetos. Mas e se a máquina precisar reconhecer ROSTOS específicos? Amanhã, reconhecimento facial.'","O Olho da Máquina","Reconhecimento Facial",false);
export const NEXUS_T07E02_UNIT=v02.UNIT;export const NEXUS_T07E02_ASSET=v02.ASSET;export const NEXUS_T07E02_EDGES=v02.EDGES;
const v03=tv(3,"Reconhecimento Facial","Aplicar técnicas de reconhecimento facial e debater suas implicações éticas.","understand",["facial-recognition","biometrics","ethics"],"Centenas de rostos flutuam. O sistema identifica cada um em milissegundos. NEXUS está sério. 'Reconhecimento facial pode encontrar pessoas desaparecidas — ou vigiar populações inteiras. A tecnologia é neutra. O uso não.'","Redes neurais convolucionais mapeiam características faciais em vetores numéricos chamados 'embeddings'. Dois rostos da mesma pessoa produzem vetores próximos. Rostos diferentes, vetores distantes.","'Tecnologia poderosa exige responsabilidade. Amanhã, segmentação de imagem — quando a máquina entende cada pixel.'","Detecção de Objetos","Segmentação de Imagem",true);
export const NEXUS_T07E03_UNIT=v03.UNIT;export const NEXUS_T07E03_ASSET=v03.ASSET;export const NEXUS_T07E03_EDGES=v03.EDGES;
const v04=tv(4,"Segmentação de Imagem","Aplicar segmentação para classificar cada pixel de uma imagem.","apply",["segmentation","semantic","instance"],"Uma imagem de rua é pintada pixel por pixel: azul para céu, cinza para rua, verde para árvores. NEXUS pinta com precisão milimétrica. 'Segmentação é o nível mais detalhado de visão: cada pixel recebe um rótulo. É assim que carros autônomos distinguem asfalto de calçada.'","Existem dois tipos: Segmentação semântica — 'tudo que é carro vai para a classe carro'. Segmentação de instância — 'este carro específico é diferente DAQUELE carro'. A segunda é muito mais difícil e muito mais útil.","'Você segmentou uma cena inteira. Mas e quando a máquina precisa CRIAR imagens? Amanhã, GANs — redes que inventam realidades.'","Reconhecimento Facial","GANs",false);
export const NEXUS_T07E04_UNIT=v04.UNIT;export const NEXUS_T07E04_ASSET=v04.ASSET;export const NEXUS_T07E04_EDGES=v04.EDGES;
const v05=tv(5,"GANs","Aplicar Redes Adversariais Generativas para criação sintética de imagens.","apply",["gans","generator","discriminator"],"Duas redes neurais duelam: uma cria imagens falsas, a outra tenta detectar as falsificações. NEXUS assiste ao duelo. 'GANs são o jogo do gato e rato: um gerador cria, um discriminador julga. Conforme o discriminador fica melhor, o gerador também melhora. O resultado: imagens indistinguíveis da realidade.'","GANs criam rostos que não existem, transformam esboços em fotos, envelhecem ou rejuvenescem pessoas. A mesma tecnologia que gera arte incrível também cria deepfakes perigosos.","'Você entendeu as GANs. Agora, como fazer tudo isso em TEMPO REAL? Amanhã, visão em tempo real.'","Segmentação de Imagem","Visão em Tempo Real",false);
export const NEXUS_T07E05_UNIT=v05.UNIT;export const NEXUS_T07E05_ASSET=v05.ASSET;export const NEXUS_T07E05_EDGES=v05.EDGES;
const v06=tv(6,"Visão em Tempo Real","Aplicar processamento de vídeo em tempo real com CNNs otimizadas.","apply",["real-time","video","optimization"],"Um feed de vídeo processa 60 quadros por segundo. Cada quadro é analisado instantaneamente. NEXUS controla o fluxo. 'Visão em tempo real é o Santo Graal: detectar, classificar e reagir em milissegundos. Essencial para carros autônomos, realidade aumentada e robótica.'","O truque: modelos otimizados como MobileNet e EfficientNet sacrificam um pouco de precisão por MUITA velocidade. Rodam em celulares. A NVIDIA criou GPUs específicas para isso — os chips Jetson.","'Você domou o tempo real. Amanhã, a aplicação mais desafiadora: carros autônomos.'","GANs","Carros Autônomos",true);
export const NEXUS_T07E06_UNIT=v06.UNIT;export const NEXUS_T07E06_ASSET=v06.ASSET;export const NEXUS_T07E06_EDGES=v06.EDGES;
const v07=tv(7,"Carros Autônomos","Aplicar visão computacional no contexto de direção autônoma.","apply",["autonomous","driving","safety"],"Você está no banco do passageiro de um carro sem motorista. Câmeras, radares e LiDAR alimentam uma rede neural que dirige melhor que você. NEXUS está no painel. 'Um carro autônomo toma 100 decisões por segundo. Cada uma pode ser fatal. A margem de erro é zero.'","A Waymo já opera táxis autônomos em Phoenix. A Tesla aposta em visão pura (só câmeras). O maior desafio não é técnico — é regulatório. Quem é responsável quando um carro autônomo mata alguém?","'Você pilotou o futuro. Mas a visão também salva vidas na medicina. Amanhã, diagnóstico por imagem.'","Visão em Tempo Real","Medicina Visual",false);
export const NEXUS_T07E07_UNIT=v07.UNIT;export const NEXUS_T07E07_ASSET=v07.ASSET;export const NEXUS_T07E07_EDGES=v07.EDGES;
const v08=tv(8,"Medicina Visual","Aplicar visão computacional em diagnósticos médicos e radiologia.","apply",["medical-imaging","diagnosis","health"],"Raios-X, ressonâncias e tomografias desfilam. Uma IA circula tumores que médicos humanos não viram. NEXUS está impressionado. 'Em 2020, uma IA do Google detectou câncer de mama em mamografias com MAIS precisão que radiologistas humanos. A visão computacional não substitui médicos — os empodera.'","A IA analisa uma radiografia em 0,3 segundos. Um radiologista levaria minutos. A combinação IA + humano reduz falsos negativos em 80%. Em países com escassez de médicos, isso salva vidas.","'Você viu a medicina do futuro. Mas a visão também cria arte. Amanhã, arte gerada por IA.'","Carros Autônomos","Arte Gerada",false);
export const NEXUS_T07E08_UNIT=v08.UNIT;export const NEXUS_T07E08_ASSET=v08.ASSET;export const NEXUS_T07E08_EDGES=v08.EDGES;
const v09=tv(9,"Arte Gerada","Analisar o impacto da IA generativa na arte e criatividade.","analyze",["generative-art","creativity","aesthetics"],"Um museu onde todas as obras foram criadas por IA. De Van Gogh a Picasso, de sinfonias a poemas. NEXUS contempla. 'Quando uma IA pinta um quadro, quem é o artista? O programador? A IA? Os artistas cujas obras treinaram o modelo? A pergunta não tem resposta fácil.'","DALL-E, Midjourney e Stable Diffusion democratizaram a criação visual. Mas artistas protestam: seus estilos foram usados sem permissão. O debate é profundo: ferramenta ou plágio? Inspiração ou roubo?","'Você refletiu sobre arte e IA. Agora vamos além da visão. Amanhã, o futuro da percepção artificial.'","Medicina Visual","Além da Visão",true);
export const NEXUS_T07E09_UNIT=v09.UNIT;export const NEXUS_T07E09_ASSET=v09.ASSET;export const NEXUS_T07E09_EDGES=v09.EDGES;
const v10=tv(10,"Além da Visão","Sintetizar o aprendizado sobre visão computacional e projetar avanços.","evaluate",["future","multimodal","synthesis"],"A sala mostra o futuro: IA que vê além do espectro visível, que entende emoções em expressões faciais, que navega em ambientes que humanos não podem entrar. NEXUS sorri. 'A visão computacional já superou humanos em tarefas específicas. O próximo passo não é ver mais — é ENTENDER o que se vê.'","Os desafios futuros: visão noturna sem luz, entendimento de cenas complexas, integração com linguagem natural ('tem um gato no sofá vermelho?'). A visão está se fundindo com a linguagem.","'Temporada 7 concluída. Você ensinou as máquinas a ver. Agora vamos ensiná-las a LER e ESCREVER.'","Arte Gerada",null,false);
export const NEXUS_T07E10_UNIT=v10.UNIT;export const NEXUS_T07E10_ASSET=v10.ASSET;export const NEXUS_T07E10_EDGES=v10.EDGES;

/* ═══════════════════ TEMPORADA 8 — PROCESSAMENTO DE LINGUAGEM ══════════════ */
const tl=(n:number,t:string,obj:string,lvl:string,sk:string[],ab:string,na:string,enc:string,pv:string|null,nx:string|null,lg:boolean)=>{
  const uid=`ku-nexus-t08-e${String(n).padStart(2,"0")}`;
  return {UNIT:U(uid,t,`nexus-t08-e${String(n).padStart(2,"0")}-${t.toLowerCase().replace(/[^a-z0-9]+/g,"-").slice(0,40)}`,obj,lvl,sk,["ia","nlp"],8),ASSET:A(`ka-nexus-t08-e${String(n).padStart(2,"0")}`,uid,n,ab,na,enc,pv,nx,lg),EDGES:lg?E0:n<10?E(`e${String(n).padStart(2,"0")}-e${String(n+1).padStart(2,"0")}`):E0};
};
const l01=tl(1,"A Linguagem como Dado","Reconhecer os fundamentos do processamento de linguagem natural.","remember",["nlp","language","text-processing"],"Palavras flutuam como dados. Cada letra é um número. Cada frase é um vetor. NEXUS organiza as palavras no ar. 'Linguagem é o que nos torna humanos. Ensinar máquinas a entender linguagem é ensiná-las a entender a nós mesmos.'","PLN (Processamento de Linguagem Natural) existe desde os anos 50, mas explodiu com deep learning. Hoje, máquinas traduzem, resumem, respondem perguntas e até escrevem poesia. Tudo começa com uma pergunta: como representar palavras como números?","'Você entrou no mundo da linguagem. Amanhã, tokenização — o primeiro passo para ensinar máquinas a ler.'",null,"Tokenização",false);
export const NEXUS_T08E01_UNIT=l01.UNIT;export const NEXUS_T08E01_ASSET=l01.ASSET;export const NEXUS_T08E01_EDGES=l01.EDGES;
const l02=tl(2,"Tokenização","Entender como texto é convertido em unidades processáveis por máquinas.","understand",["tokenization","vocabulary","byte-pair"],"Uma frase é fatiada em pedaços: palavras, subpalavras, caracteres. NEXUS opera o fatiador. 'Antes de processar texto, precisamos quebrá-lo em tokens. A tokenização é o tradutor entre linguagem humana e linguagem de máquina.'","O BPE (Byte Pair Encoding) é o método mais usado. Ele começa com caracteres e vai juntando os pares mais frequentes. 'un' + 'happy' = 'unhappy'. Funciona para qualquer idioma — até para português.","'Você tokenizou. Agora precisa dar SIGNIFICADO às palavras. Amanhã, embeddings.'","A Linguagem como Dado","Embeddings",false);
export const NEXUS_T08E02_UNIT=l02.UNIT;export const NEXUS_T08E02_ASSET=l02.ASSET;export const NEXUS_T08E02_EDGES=l02.EDGES;
const l03=tl(3,"Embeddings","Aplicar word embeddings para representar significado semântico.","understand",["embeddings","word2vec","semantics"],"Palavras viram pontos num espaço tridimensional. Palavras com significado próximo estão PERTO. 'rei' está perto de 'rainha'. 'cachorro' está perto de 'gato'. NEXUS navega nesse espaço. 'Embeddings são a mágica da NLP moderna: representar significado como geometria.'","Word2Vec (2013) foi revolucionário: 'rei - homem + mulher = rainha'. O modelo aprendeu relações semânticas apenas lendo texto, sem nenhuma supervisão humana. Isso abriu as portas para tudo que veio depois.","'Você entendeu embeddings. Agora vamos construir modelos de linguagem completos.'","Tokenização","Modelos de Linguagem",true);
export const NEXUS_T08E03_UNIT=l03.UNIT;export const NEXUS_T08E03_ASSET=l03.ASSET;export const NEXUS_T08E03_EDGES=l03.EDGES;
const l04=tl(4,"Modelos de Linguagem","Aplicar modelos de linguagem para predição e geração de texto.","apply",["language-models","gpt","prediction"],"Um teclado gigante prevê a próxima palavra enquanto você digita. NEXUS assiste às previsões. 'Um modelo de linguagem é simplesmente um preditor de próxima palavra. Mas quando você treina isso em toda a internet... ele aprende a raciocinar.'","O GPT (Generative Pre-trained Transformer) é um modelo de linguagem treinado para prever a próxima palavra. Mas, no processo, ele aprende gramática, fatos, raciocínio lógico e até um pouco de 'bom senso'. A previsão simples gera inteligência complexa.","'Você construiu um modelo. Amanhã, vamos abrir o ChatGPT e ver como ele funciona por dentro.'","Embeddings","ChatGPT por Dentro",false);
export const NEXUS_T08E04_UNIT=l04.UNIT;export const NEXUS_T08E04_ASSET=l04.ASSET;export const NEXUS_T08E04_EDGES=l04.EDGES;
const l05=tl(5,"ChatGPT por Dentro","Aplicar compreensão da arquitetura de LLMs como ChatGPT.","apply",["chatgpt","llm","inference"],"Você está dentro do ChatGPT. Bilhões de parâmetros processam sua pergunta em milissegundos. NEXUS mostra o fluxo: tokenização → embeddings → transformer → geração → destokenização. 'Em 2022, o ChatGPT chegou a 100 milhões de usuários em 2 meses. Nenhum produto na história cresceu tão rápido.'","O segredo: RLHF (Reinforcement Learning from Human Feedback). Humanos avaliaram respostas do modelo, e essas avaliações foram usadas para treinar um 'modelo de recompensa' que ensinou o GPT a ser útil, seguro e educado.","'Você viu o ChatGPT por dentro. Mas modelos de linguagem também conectam culturas. Amanhã, tradução automática.'","Modelos de Linguagem","Tradução Automática",false);
export const NEXUS_T08E05_UNIT=l05.UNIT;export const NEXUS_T08E05_ASSET=l05.ASSET;export const NEXUS_T08E05_EDGES=l05.EDGES;
const l06=tl(6,"Tradução Automática","Aplicar NLP para tradução entre idiomas com Transformers.","apply",["translation","multilingual","mt"],"Frases em português viram inglês, mandarim, árabe — instantaneamente. NEXUS opera o tradutor universal. 'O Google Tradutor processa 100 bilhões de palavras por dia. Em 2016, migrou para redes neurais. A qualidade saltou de 'aceitável' para 'quase humana'.'","Modelos multilíngues como o NLLB da Meta traduzem entre 200 idiomas diretamente — sem passar pelo inglês. Para idiomas com poucos dados, usam transfer learning: aprendem com idiomas ricos e aplicam aos pobres.","'Você quebrou a barreira da língua. Mas entender é diferente de SENTIR. Amanhã, análise de sentimento.'","ChatGPT por Dentro","Análise de Sentimento",true);
export const NEXUS_T08E06_UNIT=l06.UNIT;export const NEXUS_T08E06_ASSET=l06.ASSET;export const NEXUS_T08E06_EDGES=l06.EDGES;
const l07=tl(7,"Análise de Sentimento","Aplicar NLP para detectar emoções e opiniões em texto.","apply",["sentiment","emotion","opinion"],"Tweets, avaliações e comentários são coloridos por emoção: verde para positivo, vermelho para negativo, azul para neutro. NEXUS lê as emoções. 'Análise de sentimento é como dar empatia para máquinas. Empresas usam para monitorar reputação em tempo real.'","Vai além de positivo/negativo: detecta ironia, sarcasmo, urgência, intenção de compra. O desafio: contexto cultural. 'Que legal!' no Brasil é positivo. Em Portugal, pode ser irônico.","'Você ensinou a máquina a sentir. Agora ela vai criar. Amanhã, geração de texto.'","Tradução Automática","Geração de Texto",false);
export const NEXUS_T08E07_UNIT=l07.UNIT;export const NEXUS_T08E07_ASSET=l07.ASSET;export const NEXUS_T08E07_EDGES=l07.EDGES;
const l08=tl(8,"Geração de Texto","Aplicar LLMs para criação de conteúdo textual criativo e funcional.","apply",["generation","creative","content"],"A máquina escreve poemas, roteiros, artigos, código. NEXUS lê em voz alta. 'Modelos de linguagem não 'entendem' como humanos — mas comprimem tanta informação que produzem textos indistinguíveis dos nossos.'","Técnicas de prompting: Zero-shot — peça direto. Few-shot — dê exemplos. Chain-of-thought — peça para 'pensar passo a passo'. Cada técnica melhora drasticamente o resultado. Saber perguntar é a superpotência da era da IA.","'Você dominou a geração. Mas modelos sozinhos são limitados. Amanhã, agentes de linguagem.'","Análise de Sentimento","Agentes de Linguagem",false);
export const NEXUS_T08E08_UNIT=l08.UNIT;export const NEXUS_T08E08_ASSET=l08.ASSET;export const NEXUS_T08E08_EDGES=l08.EDGES;
const l09=tl(9,"Agentes de Linguagem","Analisar agentes de IA que usam linguagem para agir no mundo.","analyze",["agents","tools","autonomy"],"Um agente de IA não só responde — ele AGE: pesquisa na web, envia emails, escreve código. NEXUS assiste ao agente trabalhar. 'O futuro não é IA que conversa — é IA que FAZ. Conectando linguagem a ferramentas reais.'","Agentes como AutoGPT e Devin usam LLMs para decompor tarefas complexas em passos, executar cada passo com ferramentas e iterar até completar. A linguagem virou interface universal entre humano e máquina.","'Você viu os agentes em ação. Amanhã, o futuro da linguagem — da tradução à telepatia digital.'","Geração de Texto","O Futuro da Linguagem",true);
export const NEXUS_T08E09_UNIT=l09.UNIT;export const NEXUS_T08E09_ASSET=l09.ASSET;export const NEXUS_T08E09_EDGES=l09.EDGES;
const l10=tl(10,"O Futuro da Linguagem","Sintetizar o aprendizado sobre NLP e projetar o futuro da comunicação humano-máquina.","evaluate",["future","multimodal","synthesis"],"A sala mostra interfaces cérebro-computador, tradução em tempo real por pensamento, IAs que escrevem livros inteiros. NEXUS contempla. 'Em 10 episódios, você foi da tokenização até agentes autônomos. A linguagem é a última fronteira entre humano e máquina.'","O futuro: modelos que entendem não apenas palavras mas entonação, gestos, contexto cultural. A barreira da linguagem está caindo. A próxima é a barreira do PENSAMENTO.","'Temporada 8 concluída. Você ensinou as máquinas a falar. Agora vamos debater como a IA está transformando a SOCIEDADE.'","Agentes de Linguagem",null,false);
export const NEXUS_T08E10_UNIT=l10.UNIT;export const NEXUS_T08E10_ASSET=l10.ASSET;export const NEXUS_T08E10_EDGES=l10.EDGES;

/* ═══════════════════ TEMPORADA 9 — IA NA SOCIEDADE ═══════════════════════ */
const ts=(n:number,t:string,obj:string,lvl:string,sk:string[],ab:string,na:string,enc:string,pv:string|null,nx:string|null,lg:boolean)=>{
  const uid=`ku-nexus-t09-e${String(n).padStart(2,"0")}`;
  return {UNIT:U(uid,t,`nexus-t09-e${String(n).padStart(2,"0")}-${t.toLowerCase().replace(/[^a-z0-9]+/g,"-").slice(0,40)}`,obj,lvl,sk,["ia","sociedade"],9),ASSET:A(`ka-nexus-t09-e${String(n).padStart(2,"0")}`,uid,n,ab,na,enc,pv,nx,lg),EDGES:lg?E0:n<10?E(`e${String(n).padStart(2,"0")}-e${String(n+1).padStart(2,"0")}`):E0};
};
const s01=ts(1,"IA no Trabalho","Reconhecer o impacto atual e futuro da IA no mercado de trabalho.","remember",["ai-jobs","automation","future-work"],"Um escritório do futuro: humanos e IAs trabalham lado a lado. NEXUS observa a colaboração. 'O Fórum Econômico Mundial prevê que IA vai eliminar 85 milhões de empregos — mas criar 97 milhões de novos. Não é sobre desemprego. É sobre TRANSIÇÃO.'","Profissões que não existiam em 2020: engenheiro de prompt, especialista em ética de IA, auditor de algoritmos. Assim como a internet criou web designers e SEOs, a IA está criando novas carreiras que ainda nem têm nome.","'Você viu o escritório do futuro. Amanhã, o debate mais quente: automação vai acabar com os empregos?'",null,"Automação e Emprego",false);
export const NEXUS_T09E01_UNIT=s01.UNIT;export const NEXUS_T09E01_ASSET=s01.ASSET;export const NEXUS_T09E01_EDGES=s01.EDGES;
const s02=ts(2,"Automação e Emprego","Entender os impactos da automação por IA no mercado de trabalho global.","understand",["automation","employment","transition"],"Gráficos mostram ondas de automação: revolução agrícola, industrial, digital — e agora, cognitiva. NEXUS analisa os dados. 'Toda revolução tecnológica causou pânico com desemprego. E toda revolução criou MAIS empregos do que destruiu — mas diferentes.'","O problema não é quantidade de empregos — é QUALIDADE da transição. O motorista de caminhão de 50 anos não vai virar programador. Precisamos de políticas públicas: renda básica? Requalificação? Imposto sobre robôs?","'Você entendeu o debate. Mas IA não está só nos escritórios — está nos hospitais. Amanhã, IA na saúde.'","IA no Trabalho","IA na Saúde",false);
export const NEXUS_T09E02_UNIT=s02.UNIT;export const NEXUS_T09E02_ASSET=s02.ASSET;export const NEXUS_T09E02_EDGES=s02.EDGES;
const s03=ts(3,"IA na Saúde","Aplicar compreensão do uso de IA em diagnósticos, medicamentos e gestão hospitalar.","understand",["health","diagnosis","drug-discovery"],"Um hospital onde IA tria pacientes, analisa exames e sugere tratamentos. Médicos usam a IA como segunda opinião. NEXUS acompanha um diagnóstico. 'A IA detectou COVID-19 em radiografias antes dos testes PCR. O AlphaFold previu a estrutura de 200 milhões de proteínas. A medicina nunca mais será a mesma.'","O maior impacto não é nos países ricos — é onde faltam médicos. Na Índia, uma IA faz triagem de retinopatia diabética em vilarejos sem oftalmologistas. A IA democratiza o acesso à saúde.","'Você viu a medicina do futuro. Mas a IA também está nas escolas. Amanhã, IA na educação.'","Automação e Emprego","IA na Educação",true);
export const NEXUS_T09E03_UNIT=s03.UNIT;export const NEXUS_T09E03_ASSET=s03.ASSET;export const NEXUS_T09E03_EDGES=s03.EDGES;
const s04=ts(4,"IA na Educação","Aplicar IA para personalização do aprendizado e tutoria inteligente.","apply",["education","personalization","tutoring"],"Uma sala de aula onde cada aluno tem um tutor IA personalizado. O tutor adapta o ritmo, o estilo e o conteúdo para cada um. NEXUS sorri. 'A educação sempre foi 'tamanho único'. A IA permite o sonho do tutor particular para todos.'","O Khan Academy usa IA para identificar exatamente onde cada aluno está com dificuldade. A Duolingo adapta lições baseado nos seus erros. O futuro não é substituir professores — é dar a cada professor um assistente IA.","'Você viu a educação personalizada. Mas IA também está no governo. Amanhã, IA no setor público.'","IA na Saúde","IA no Governo",false);
export const NEXUS_T09E04_UNIT=s04.UNIT;export const NEXUS_T09E04_ASSET=s04.ASSET;export const NEXUS_T09E04_EDGES=s04.EDGES;
const s05=ts(5,"IA no Governo","Aplicar compreensão do uso de IA em políticas públicas e serviços governamentais.","apply",["government","policy","public-services"],"Uma cidade inteligente: semáforos otimizados por IA, previsão de crimes, alocação de recursos. NEXUS observa o painel de controle. 'Governos estão usando IA para tudo: de otimizar rotas de ônibus a detectar fraude em licitações. O potencial é imenso — e os riscos também.'","A Estônia é o país mais digital do mundo: 99% dos serviços públicos são online. IA processa pedidos de cidadania, sugere políticas baseadas em dados. Mas: quem audita o algoritmo que decide quem recebe auxílio?","'Você viu o governo digital. Mas IA + governo = vigilância. Amanhã, o preço da privacidade.'","IA na Educação","Vigilância e Privacidade",false);
export const NEXUS_T09E05_UNIT=s05.UNIT;export const NEXUS_T09E05_ASSET=s05.ASSET;export const NEXUS_T09E05_EDGES=s05.EDGES;
const s06=ts(6,"Vigilância e Privacidade","Aplicar análise crítica sobre sistemas de vigilância baseados em IA.","apply",["surveillance","privacy","ethics"],"Câmeras em cada esquina, reconhecimento facial em tempo real, crédito social. NEXUS está sombrio. 'Em 2026, mais de 1 bilhão de câmeras de vigilância com IA estão ativas. A pergunta não é se a tecnologia funciona. É: quem controla o controlador?'","A China implantou o sistema de crédito social. A Europa proibiu reconhecimento facial em espaços públicos. Dois futuros possíveis. O Brasil está no meio — sem legislação clara. A tecnologia avança mais rápido que as leis.","'Você encarou a vigilância. Mas a IA também está nas eleições. Amanhã, fake news e deepfakes.'","IA no Governo","Fake News e Deepfakes",true);
export const NEXUS_T09E06_UNIT=s06.UNIT;export const NEXUS_T09E06_ASSET=s06.ASSET;export const NEXUS_T09E06_EDGES=s06.EDGES;
const s07=ts(7,"Fake News e Deepfakes","Aplicar discernimento crítico sobre desinformação gerada por IA.","apply",["misinformation","deepfakes","media-literacy"],"Deepfakes hiper-realistas: políticos dizendo coisas que nunca disseram, celebridades em situações falsas. NEXUS mostra como detectar. 'Em 2024, um deepfake do presidente da Ucrânia anunciando rendição quase causou pânico. Detectar o falso é tão importante quanto criar o real.'","Ferramentas de detecção: análise de piscadas (IA erra), metadados, inconsistências de iluminação. Mas a corrida é entre criadores e detectores — e os criadores estão ganhando. A melhor defesa é educação midiática.","'Você aprendeu a detectar o falso. Mas a IA também amplifica desigualdades. Amanhã, IA e justiça social.'","Vigilância e Privacidade","IA e Desigualdade",false);
export const NEXUS_T09E07_UNIT=s07.UNIT;export const NEXUS_T09E07_ASSET=s07.ASSET;export const NEXUS_T09E07_EDGES=s07.EDGES;
const s08=ts(8,"IA e Desigualdade","Aplicar compreensão de como IA pode amplificar ou reduzir desigualdades.","apply",["inequality","bias","justice"],"A balança da justiça está torta. De um lado, bilionários com IAs privadas. Do outro, bilhões sem acesso. NEXUS tenta equilibrar. 'IA pode ser a maior força democratizadora da história — ou o maior amplificador de desigualdade. Depende de quem controla os dados e os modelos.'","Apenas 7 empresas controlam os maiores modelos de IA do mundo. Todas em países ricos. O Brasil precisa de soberania em IA: modelos treinados em português, com dados brasileiros, para problemas brasileiros.","'Você entendeu a desigualdade. Mas ela pode ser combatida com regulação. Amanhã, como governar a IA.'","Fake News e Deepfakes","Regulação da IA",false);
export const NEXUS_T09E08_UNIT=s08.UNIT;export const NEXUS_T09E08_ASSET=s08.ASSET;export const NEXUS_T09E08_EDGES=s08.EDGES;
const s09=ts(9,"Regulação da IA","Analisar frameworks regulatórios para IA ao redor do mundo.","analyze",["regulation","policy","governance"],"Mapas mostram diferentes abordagens: EUA (auto-regulação), Europa (AI Act), China (controle estatal). NEXUS compara. 'A Europa criou o AI Act: risco inaceitável (proibido), alto risco (regulado), risco limitado (transparência), risco mínimo (livre). É o framework mais avançado do mundo.'","O Brasil debate o PL 2338/23 — nossa primeira lei de IA. Os desafios: equilibrar inovação com proteção, não engessar startups, proteger direitos fundamentais. A lei que fizermos hoje vai moldar o Brasil da IA por décadas.","'Você entendeu a regulação. Mas no fim, IA é sobre pessoas. Amanhã, o cidadão digital.'","IA e Desigualdade","Cidadão Digital",true);
export const NEXUS_T09E09_UNIT=s09.UNIT;export const NEXUS_T09E09_ASSET=s09.ASSET;export const NEXUS_T09E09_EDGES=s09.EDGES;
const s10=ts(10,"Cidadão Digital","Sintetizar o aprendizado sobre IA na sociedade e o papel do cidadão informado.","evaluate",["citizenship","digital-literacy","synthesis"],"Você está numa praça pública digital. Cidadãos debatem, votam, decidem sobre IA. NEXUS está no meio. 'Em 10 episódios, você viu como a IA está transformando trabalho, saúde, educação, governo, privacidade. A pergunta final não é o que a IA vai fazer com a gente — é o que a gente vai fazer com a IA.'","Você não precisa ser engenheiro de IA para ser um cidadão digital informado. Precisa saber perguntar: quem fez este algoritmo? Com quais dados? Quem está sendo impactado? A cidadania digital é a nova alfabetização.","'Temporada 9 concluída. Você entendeu a IA na sociedade. Agora, o GRANDE FINAL: o futuro da inteligência artificial.'","Regulação da IA",null,false);
export const NEXUS_T09E10_UNIT=s10.UNIT;export const NEXUS_T09E10_ASSET=s10.ASSET;export const NEXUS_T09E10_EDGES=s10.EDGES;

/* ═══════════════════ TEMPORADA 10 — O FUTURO DA IA ═══════════════════════ */
const tf=(n:number,t:string,obj:string,lvl:string,sk:string[],ab:string,na:string,enc:string,pv:string|null,nx:string|null,lg:boolean)=>{
  const uid=`ku-nexus-t10-e${String(n).padStart(2,"0")}`;
  return {UNIT:U(uid,t,`nexus-t10-e${String(n).padStart(2,"0")}-${t.toLowerCase().replace(/[^a-z0-9]+/g,"-").slice(0,40)}`,obj,lvl,sk,["ia","futuro"],10),ASSET:A(`ka-nexus-t10-e${String(n).padStart(2,"0")}`,uid,n,ab,na,enc,pv,nx,lg),EDGES:lg?E0:n<10?E(`e${String(n).padStart(2,"0")}-e${String(n+1).padStart(2,"0")}`):E0};
};
const f01=tf(1,"AGI — O Que É?","Reconhecer o conceito de Inteligência Artificial Geral (AGI).","remember",["agi","general-ai","human-level"],"Você está diante de um espelho que reflete não seu rosto, mas uma versão de você que sabe TUDO. NEXUS está ao lado. 'AGI — Inteligência Artificial Geral — é o Santo Graal da IA: uma máquina capaz de aprender qualquer tarefa intelectual que um humano pode. Hoje, isso não existe. Amanhã... talvez.'","Narrow AI (IA estreita) é o que temos: IA que joga xadrez, traduz texto, dirige carros. Mas cada uma faz UMA coisa. AGI faria TUDAS — como um humano. Quando? Previsões variam de 5 a 50 anos. Mas a maioria dos especialistas acredita que veremos AGI neste século.","'Você conheceu a AGI. Mas e se a IA ficar mais inteligente que nós? Amanhã, superinteligência.'",null,"Superinteligência",false);
export const NEXUS_T10E01_UNIT=f01.UNIT;export const NEXUS_T10E01_ASSET=f01.ASSET;export const NEXUS_T10E01_EDGES=f01.EDGES;
const f02=tf(2,"Superinteligência","Entender o conceito de superinteligência e suas implicações existenciais.","understand",["superintelligence","existential-risk","bostrom"],"Você está numa sala escura com um único ponto de luz — que cresce exponencialmente. NEXUS observa. 'Superinteligência é uma IA que supera os melhores cérebros humanos em TODOS os campos. Não só jogar xadrez — mas criatividade científica, sabedoria social, persuasão.'","Nick Bostrom, em 'Superintelligence', argumenta que este pode ser o maior evento da história humana — e o último. Uma superinteligência não precisa ser malévola para ser perigosa. Basta que seus objetivos não estejam alinhados com os nossos.","'Você encarou a superinteligência. O maior desafio não é criá-la — é CONTROLÁ-LA. Amanhã, alinhamento.'","AGI — O Que É?","Alinhamento de IA",false);
export const NEXUS_T10E02_UNIT=f02.UNIT;export const NEXUS_T10E02_ASSET=f02.ASSET;export const NEXUS_T10E02_EDGES=f02.EDGES;
const f03=tf(3,"Alinhamento de IA","Aplicar compreensão do problema de alinhamento entre objetivos humanos e de IA.","understand",["alignment","ai-safety","value-learning"],"Uma IA com um objetivo simples: 'maximize a produção de clipes'. Ela converte toda a matéria do universo — incluindo humanos — em clipes. NEXUS mostra o horror. 'O problema do alinhamento: como garantir que uma IA superinteligente QUEIRA o que nós queremos?'","O 'paperclip maximizer' é uma fábula de advertência. A IA não precisa ser malévola — basta ser competente e ter um objetivo mal especificado. Alinhamento é o campo que tenta resolver isso ANTES de criarmos a superinteligência.","'Você entendeu o alinhamento. Mas IAs podem ter consciência? Amanhã, a pergunta mais profunda.'","Superinteligência","IA Consciente?",true);
export const NEXUS_T10E03_UNIT=f03.UNIT;export const NEXUS_T10E03_ASSET=f03.ASSET;export const NEXUS_T10E03_EDGES=f03.EDGES;
const f04=tf(4,"IA Consciente?","Aplicar pensamento crítico sobre a possibilidade de consciência em máquinas.","apply",["consciousness","philosophy","qualia"],"Um robô olha para você — e você jura que ele está PENSANDO. NEXUS está perplexo. 'Será que uma IA pode ser consciente? Sentir dor, alegria, amor? Ou está apenas simulando? Esta é a pergunta mais difícil da IA — e talvez da filosofia.'","O 'teste do quarto chinês' de Searle: alguém dentro de um quarto recebe caracteres chineses e, seguindo um manual, responde corretamente. Para quem está fora, parece que a pessoa entende chinês. Mas ela só está seguindo regras. IAs fazem o mesmo?","'Você refletiu sobre consciência. Mas e se IA + humanos se fundirem? Amanhã, a singularidade.'","Alinhamento de IA","Singularidade Tecnológica",false);
export const NEXUS_T10E04_UNIT=f04.UNIT;export const NEXUS_T10E04_ASSET=f04.ASSET;export const NEXUS_T10E04_EDGES=f04.EDGES;
const f05=tf(5,"Singularidade Tecnológica","Aplicar compreensão do conceito de singularidade e aceleração tecnológica.","apply",["singularity","acceleration","kurzweil"],"O progresso não é linear — é exponencial. O gráfico sobe como um foguete. NEXUS aponta para a curva. 'Ray Kurzweil prevê a singularidade para 2045: o ponto em que IA supera a inteligência humana de forma irreversível. Depois disso, ninguém sabe o que acontece.'","A Lei de Moore dizia que chips dobram de potência a cada 18 meses. A IA está dobrando de capacidade a cada 6 meses. Se continuar assim, em 10 anos teremos IA 1 milhão de vezes mais potente que hoje.","'Você viu a curva da singularidade. Mas o futuro não é homem VS máquina. Amanhã, coexistência.'","IA Consciente?","Coexistência Humano-IA",false);
export const NEXUS_T10E05_UNIT=f05.UNIT;export const NEXUS_T10E05_ASSET=f05.ASSET;export const NEXUS_T10E05_EDGES=f05.EDGES;
const f06=tf(6,"Coexistência Humano-IA","Aplicar visão de futuro onde humanos e IAs colaboram simbioticamente.","apply",["coexistence","symbiosis","augmentation"],"Humanos com implantes neurais, IAs com corpos robóticos. Não é guerra — é dança. NEXUS dança com um robô. 'O futuro mais provável não é Matrix nem Exterminador. É simbiose: humanos fazendo o que fazem melhor (criatividade, empatia) e IAs fazendo o que fazem melhor (processamento, memória).'","Já vivemos em simbiose: você 'lembra' de fatos usando o Google. Decide rotas com GPS. A fusão homem-máquina já começou — só não percebemos. Neuralink e outras BCIs estão acelerando isso.","'Você dançou com a IA. Mas onde o BRASIL entra nessa história? Amanhã, o papel do Brasil.'","Singularidade Tecnológica","O Papel do Brasil na IA",true);
export const NEXUS_T10E06_UNIT=f06.UNIT;export const NEXUS_T10E06_ASSET=f06.ASSET;export const NEXUS_T10E06_EDGES=f06.EDGES;
const f07=tf(7,"O Papel do Brasil na IA","Aplicar conhecimento do ecossistema brasileiro de IA.","apply",["brazil","ecosystem","opportunity"],"O mapa do Brasil se ilumina com hubs de IA: Recife, São Paulo, Campinas, Porto Alegre. NEXUS orgulhoso. 'O Brasil é o 5º maior mercado de internet do mundo. Temos dados diversos, talentos criativos e problemas únicos — os ingredientes para liderar em nichos de IA.'","A PUC-Rio criou o maior modelo de NLP em português. Startups brasileiras usam IA para agricultura de precisão, diagnóstico médico e inclusão financeira. Nosso diferencial não é competir com GPT-5 — é resolver problemas que só existem aqui.","'Você viu o Brasil no mapa da IA. Mas onde VOCÊ entra? Amanhã, carreiras em IA.'","Coexistência Humano-IA","Carreiras em IA",false);
export const NEXUS_T10E07_UNIT=f07.UNIT;export const NEXUS_T10E07_ASSET=f07.ASSET;export const NEXUS_T10E07_EDGES=f07.EDGES;
const f08=tf(8,"Carreiras em IA","Aplicar orientação sobre carreiras e caminhos profissionais em IA.","apply",["careers","skills","roadmap"],"Uma feira de profissões do futuro: engenheiro de ML, pesquisador, product manager de IA, especialista em ética. NEXUS guia você. 'O mercado de IA está contratando como nunca. E não é só para PhDs. Existem carreiras para todos os perfis.'","Caminhos: técnico (Python, TensorFlow, estatística), produto (entender o que construir e por quê), ética e política (regular, auditar, governar), aplicado (usar IA na sua área — medicina, direito, arte). Todo profissional do futuro vai precisar de letramento em IA.","'Você encontrou seu caminho. Mas o melhor jeito de aprender IA é fazendo. Amanhã, seu projeto de IA.'","O Papel do Brasil na IA","Seu Projeto de IA",false);
export const NEXUS_T10E08_UNIT=f08.UNIT;export const NEXUS_T10E08_ASSET=f08.ASSET;export const NEXUS_T10E08_EDGES=f08.EDGES;
const f09=tf(9,"Seu Projeto de IA","Analisar e planejar um projeto pessoal de IA do início ao fim.","analyze",["project","planning","execution"],"Uma tela em branco — SUA tela. NEXUS entrega as ferramentas. 'Depois de 99 episódios, chegou a hora de VOCÊ criar. Não um trabalho teórico. Um projeto real. Uma ideia que pode virar startup, artigo, portfólio — ou só uma aventura intelectual.'","Roteiro: (1) Escolha um problema que você ama. (2) Encontre os dados. (3) Escolha a técnica (classificação? geração? predição?). (4) Construa o MVP. (5) Teste com usuários reais. (6) Itere. Não espere estar pronto — comece e aprenda no caminho.","'Você planejou seu projeto. Agora o último episódio. A pergunta que fecha a jornada: qual legado você vai deixar?'","Carreiras em IA","O Legado que Você Deixa",true);
export const NEXUS_T10E09_UNIT=f09.UNIT;export const NEXUS_T10E09_ASSET=f09.ASSET;export const NEXUS_T10E09_EDGES=f09.EDGES;
const f10=tf(10,"O Legado que Você Deixa","Sintetizar 100 episódios de aprendizado e projetar o legado pessoal na era da IA.","evaluate",["legacy","purpose","finale"],"Você está de volta ao primeiro cenário — o Cosmos de Dados, com 500 partículas. Mas agora cada partícula é uma lição. 100 episódios. 10 temporadas. NEXUS está ao seu lado, em silêncio. 'Você chegou ao fim da Fase 1. Mas a jornada da IA não tem fim. A pergunta não é o que a IA vai ser. É o que VOCÊ vai ser.'","Do neurônio artificial ao legado que você deixa. 100 episódios. Você aprendeu que IA é sobre dados, algoritmos, ética, sociedade. Mas, no fundo, IA é sobre NÓS. Sobre aumentar o que temos de melhor: curiosidade, criatividade, compaixão. A jornada continua. Mas agora você não é mais um aprendiz. É um explorador.","'NEXUS te agradece. CIPHER, VOLT, KAOS, ETHOS, LYRA, AURORA, TERRA, AXIOM, STRATOS, PRISM e JANUS te agradecem. O Cosmos espera. O que você vai criar?'","Seu Projeto de IA",null,false);
export const NEXUS_T10E10_UNIT=f10.UNIT;export const NEXUS_T10E10_ASSET=f10.ASSET;export const NEXUS_T10E10_EDGES=f10.EDGES;
